import lombok.spi.Provides;

import com.sun.tools.javac.code.Flags;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;

/**
 * Handles the {@code lombok.FieldDefaults} annotation for javac.
 */
@Provides(JavacASTVisitor.class)
@HandlerPriority(-2048) //-2^11; to ensure @Value picks up on messing with the fields' 'final' state, run earlier.
public class HandleFieldDefaults extends JavacASTAdapter {
	public boolean generateFieldDefaultsForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal, boolean checkForTypeLevelFieldDefaults) {
		if (checkForTypeLevelFieldDefaults) {
			if (hasAnnotation(FieldDefaults.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return true;
			}
		}

		if (!isClassOrEnum(typeNode)) {
			errorNode.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}

		for (JavacNode field : typeNode.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			//Skip fields that start with $
			if (fieldDecl.name.toString().startsWith("$")) continue;

			setFieldDefaultsForField(field, level, makeFinal);
		}

		return true;
	}

	public void setFieldDefaultsForField(JavacNode fieldNode, AccessLevel level, boolean makeFinal) {
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		if (level != null && level != AccessLevel.NONE) {
			if ((field.mods.flags & (Flags.PUBLIC | Flags.PRIVATE | Flags.PROTECTED)) == 0) {
				if (!hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, fieldNode)) {
					if ((field.mods.flags & Flags.STATIC) == 0) {
						field.mods.flags |= toJavacModifier(level);
					}
				}
			}
		}

		if (makeFinal && (field.mods.flags & Flags.FINAL) == 0) {
			if (!hasAnnotationAndDeleteIfNeccessary(NonFinal.class, fieldNode)) {
				if ((field.mods.flags & Flags.STATIC) == 0) {
					field.mods.flags |= Flags.FINAL;
				}
			}
		}

		fieldNode.rebuild();
	}

	@Override public void visitType(JavacNode typeNode, JCClassDecl type) {
		AnnotationValues<FieldDefaults> fieldDefaults = null;
		JavacNode source = typeNode;
		boolean levelIsExplicit = false;
		boolean makeFinalIsExplicit = false;
		FieldDefaults fd = null;
		for (JavacNode jn : typeNode.down()) {
			if (jn.getKind() != Kind.ANNOTATION) continue;
			JCAnnotation ann = (JCAnnotation) jn.get();
			JCTree typeTree = ann.annotationType;
			if (!typeMatches(FieldDefaults.class, jn, typeTree)) continue;
			source = jn;
			fieldDefaults = createAnnotation(FieldDefaults.class, jn);
			levelIsExplicit = fieldDefaults.isExplicit("level");
			makeFinalIsExplicit = fieldDefaults.isExplicit("makeFinal");
			URI sourceLocation = jn.getAst().getAbsoluteFileLocation();
			FlagUsageType fieldDefaultsUsage = LombokConfiguration.read(ConfigurationKeys.FIELD_DEFAULTS_FLAG_USAGE, sourceLocation);
			FlagUsageType experimentalUsage = LombokConfiguration.read(ConfigurationKeys.EXPERIMENTAL_FLAG_USAGE, sourceLocation);
			boolean errorOnFieldDefaults = fieldDefaultsUsage == FlagUsageType.ERROR;
			boolean warnOnFieldDefaults = fieldDefaultsUsage == FlagUsageType.WARNING;
			boolean errorOnExperimental = experimentalUsage == FlagUsageType.ERROR;
			FlagUsageType appliedUsage = experimentalUsage;
			String flaggedFeature = "any lombok.experimental feature";
			boolean preferFieldDefaults = errorOnFieldDefaults | (warnOnFieldDefaults & !errorOnExperimental);
			if (preferFieldDefaults) {
				appliedUsage = fieldDefaultsUsage;
				flaggedFeature = "@FieldDefaults";
			}
			if (appliedUsage != null) {
				String flaggedMessage = "Use of " + flaggedFeature + " is flagged according to lombok configuration.";
				boolean reportAsWarning = appliedUsage == FlagUsageType.WARNING;
				boolean reportAsError = appliedUsage == FlagUsageType.ERROR;
				if (reportAsWarning) {
					jn.addWarning(flaggedMessage);
				}
				if (reportAsError) {
					jn.addError(flaggedMessage);
				}
			}
			fd = fieldDefaults.getInstance();
			boolean missingExplicitSettings = !levelIsExplicit & !makeFinalIsExplicit;
			if (missingExplicitSettings) {
				jn.addError("This does nothing; provide either level or makeFinal or both.");
			}
			boolean noneAccess = levelIsExplicit & (fd.level() == AccessLevel.NONE);
			if (noneAccess) {
				jn.addError("AccessLevel.NONE doesn't mean anything here. Pick another value.");
				levelIsExplicit = false;
			}
			deleteAnnotationIfNeccessary(jn, FieldDefaults.class);
			deleteImportFromCompilationUnit(jn, "lombok.AccessLevel");
			break;
		}
		long typeFlags = type.mods.flags;
		long interfaceBit = Flags.INTERFACE;
		long annotationBit = Flags.ANNOTATION;
		boolean interfaceType = (typeFlags & interfaceBit) != 0;
		boolean annotationType = (typeFlags & annotationBit) != 0;
		boolean skipBecauseInterface = (fd == null) & interfaceType;
		boolean skipBecauseAnnotation = (fd == null) & annotationType;
		boolean skipUnsupported = skipBecauseInterface | skipBecauseAnnotation;
		if (skipUnsupported) return;
		URI compilationUnitLocation = typeNode.getAst().getAbsoluteFileLocation();
		Boolean configuredPrivate = LombokConfiguration.read(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE, compilationUnitLocation);
		Boolean configuredFinal = LombokConfiguration.read(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE, compilationUnitLocation);
		boolean configuredPrivateEnabled = Boolean.TRUE.equals(configuredPrivate);
		boolean configuredFinalEnabled = Boolean.TRUE.equals(configuredFinal);
		boolean useConfiguredPrivate = !levelIsExplicit;
		boolean useConfiguredFinal = !makeFinalIsExplicit;
		boolean defaultToPrivate = useConfiguredPrivate & configuredPrivateEnabled;
		boolean defaultToFinal = useConfiguredFinal & configuredFinalEnabled;
		if (!defaultToPrivate && !defaultToFinal && fieldDefaults == null) return;
		AccessLevel fdAccessLevel = (fieldDefaults != null && levelIsExplicit) ? fd.level() : defaultToPrivate ? AccessLevel.PRIVATE : null;
		boolean fdToFinal = (fieldDefaults != null && makeFinalIsExplicit) ? fd.makeFinal() : defaultToFinal;
		generateFieldDefaultsForType(typeNode, source, fdAccessLevel, fdToFinal, false);
	}
}

